def shortestPathAllKeys(grid: list[str]) -> int:
    R, C = len(grid), len(grid[0])
    from collections import deque
    total_keys = 0
    sr = sc = 0
    for r in range(R):
        for c in range(C):
            ch = grid[r][c]
            if ch == '@': sr, sc = r, c
            elif ch.islower(): total_keys += 1
    target_mask = (1 << total_keys) - 1
    q = deque([(sr, sc, 0, 0)])  # (r, c, keys_mask, steps)
    visited = {(sr, sc, 0)}
    while q:
        r, c, mask, d = q.popleft()
        if mask == target_mask: return d
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                ch = grid[nr][nc]
                if ch == '#': continue
                if ch.isupper() and not (mask & (1 << (ord(ch) - ord('A')))):
                    continue
                nxt_mask = mask
                if ch.islower():
                    nxt_mask |= (1 << (ord(ch) - ord('a')))
                if (nr, nc, nxt_mask) not in visited:
                    visited.add((nr, nc, nxt_mask))
                    q.append((nr, nc, nxt_mask, d + 1))
    return -1

